      "description": "Komínový odsavač Mora OV 686 GB v elegantním černém provedením s dotykovým ovládáním, 3 výkonovými rychlostmi odstraní dokonale nejen mastnotu, ale i pachy. Jedinečné kovové tukové filtry jsou vylepšené speciální polyuretanovou pěnou, která eliminuje až 98 % všech tukových a jiných nečistot. Pěna zároveň zachovává perfektní absorpční účinnost. Inovativní perimetrický odsávací systém přesměruje odsávání vzduchu z centrální části do vnějších rohů odsavače par. Tento přístup nepřetěžuje motor, optimalizuje spotřebu energie, snižuje hluk a odsávání vzduchu je podstatně účinnější. Díky zkosené přední části budete mít dostatek prostoru pro vaření, takže se nemusíte obávat, že narazíte hlavou na hranu. LED osvětlení perfektně osvítí varnou plochu, takže budete mít dokonalý přehled nad připravovaným pokrmem. S maximálním výkonem 608 m3/h a hlučností 63 dB bude neocenitelným pomocníkem ve Vaší domácnosti. Digestoř lze použít i na vnitřní cirkulaci vzduchu, stačí dokoupit uhlíkové filtry. Samozřejmostí je i zpětná klapka. Potěší Vás i možnost mýt kovové tukové filtry v myčce a tím udržovat odsavač v perfektním stavu bez zbytečné námahy.",
