      "category": "varná deska",
      "description": "Sklokeramická varná deska MORA VDSS 654 FF v černém provedení a přední hranou zkosenou, disponuje 4 Hi-Light varnými zónami, z toho se dvěma duozónami. S ukazatelem zbytkového tepla na desce víte, která zóna je ještě horká a jste tak chráněni před nepříjemným popálením a jinými nehodami. Taky můžete využít zbytkového tepla pro rozmrazovaní nebo ohřev uvařeného jídla. Dotykové ovládání s plynulou regulací výkonu se zvukovým signálem bylo navrženo tak, aby zabíralo minimum místa, ale stále Vám poskytovalo dokonalý přehled o stavu vaření. Sklokeramický povrch se velmi snadno čistí, stačí jej otřít a varná deska je opět čistá bez námahy a pohodlně. Díky funkci KeepWarm zůstane pokrm teplý i pro opozdilce, funkce udržuje stabilní teplotu zóny 70 ˚C, takže hotová jídla si tak uchovají teplotu a svou původní chuť, dokud je nebudete servírovat. Funkce KeyLock je vytvořena speciálně pro rodiny s malými dětmi. Nechat děti v kuchyni bez dozoru nebylo nikdy bezpečnější, protože tato možnost jim zamezuje zapnout varní desku. Funkce Timer vám umožní nastavit dobu vaření až na 99 minut. Pokud znáte optimální dobu vaření pro konkrétní jídlo, můžete nastavit časovač a varná deska se po uplynutí nastavené doby automaticky vypne. Pípnutí signalizuje, že je jídlo připravené. Praktická funkce Pause zastaví vaření a po opětovné aktivaci bude pokračovat se stejnými nastaveními.",
