      "name": "Vestavná trouba",
      "category": "vestavná trouba",
      "description": "Tato elektrická trouba v elegantním provedení bílého skla vám kromě tradičního pečení otevře dveře k dalším moderním tepelným úpravám pokrmu. Disponuje funkcí páry, kterou ocení především příznivci zdravé výživy. Připravíte s ní jídla rychle a šetrně, takže si zachovají maximum vitamínů a stopových prvků. Navíc vás překvapí výtečná chuť a přirozená konzistence výsledných jídel. Dále je trouba vybavená 22 automatickými pečicími programy, které jsou navržené přesně podle potřeb konkrétních jídel. Vyberte jenom typ jídla a jeho hmotnost, trouba zvolí správnou teplotu, topná tělesa a nastaví čas přípravy. Vykouzlíte například výbornou pizzu jako z italské restaurace (program Pizza 300 °C), pomalu upečete pečínku, a efektivně rozmrazíte hotové porce jídla. Pokud si rádi pochutnáváte na hranolkách nebo kuřecích nugetách, ale nedopřáváte si je tak často kvůli vysoké kalorické hodnotě, můžete také zkusit program pro horkovzdušné fritování bez tuku. Klenutý vnitřní prostor trouby je inspirovaný tradičním tvarem kamenné pece. Chytře rozmístěná topná tělesa a extra velký objem 77 l zaručují dokonale propečené a křupavé jídlo ze všech stran. Zaujme vás jistě také variabilním rozpětím teploty od 30 do 300 °C. Teleskopický výsuv zabezpečí snadnější manipulaci s nádobím, zatímco tlumené zavírání a otevírání dvířek přinese komfort při každodenním provozu. Díky dvojitému osvětlení získáte perfektní přehled, aniž byste museli troubu otevírat. Speciální dvířka CoolDoor jsou vyrobená z trojitého skla, takže zůstávají chladná, a tedy bezpečná, i během pečení. Perfektní vyčištění párou zajistí funkce ECO CLEAN, díky které odstraníte i větší nečistoty bez nutnosti použít čisticí prostředek. Trouba spadá do ekologické třídy A+.",
