      "description": "Představujeme novou generaci indukčních varných desek MORA s patentovanou technologií OptimalHeat System – pro tiché, stabilní a rovnoměrné vaření. MORA VDIS 677 FF s broušenými bočními hranami a zkosenou přední fazetou, která dodává desce jemný designový detail, přirozeně ladí s každou kuchyní. Dotykové ovládání s podsvícenými posuvnými ovladači EasySlide je intuitivní a přesné. Čtyři varné zóny automaticky rozpoznají polohu nádoby už za 0,2 sekundy a s funkcí EasyTransfer můžete hrnce jednoduše přesouvat i s nastavenými parametry. Levé varné zóny lze díky funkci FlexiZone propojit do jedné velké zóny, což usnadňuje vaření ve velkých hrncích nebo přípravu více jídel současně. Inteligentní programy neustále sledují teplotu a automaticky přizpůsobují výkon – pro dokonale uvařená jídla bez ztráty chuti. Praktické funkce jako KeepWarm (70 °C) pro udržování tepla, EasyMelt (40–45 °C) pro jemné rozpouštění či automatický program na vaření těstovin vám usnadní každodenní vaření. Silný SuperBoost zajistí extra výkon, funkce Timer a minutka TimeMinutes dohlédnou na čas a funkce Pause umožní kdykoli přerušit vaření bez ztráty nastavení.",
