      "model": "VCMDN 3024",
      "name": "Chladnička",
      "category": "chladnička",
      "description": "Vestavná kombinovaná chladnička MORA VCMDN 3024 je navržena tak, aby vám každý den usnadnila život a zároveň uchovala vaše potraviny déle čerstvé. Díky elektronickému ovládání s přehledným LED displejem jednoduše nastavíte ideální teplotu pro chladničku i mrazničku – a aktivujete i praktické režimy jako rychlé chlazení, rychlé mrazení nebo úsporný EcoMode během vaší nepřítomnosti. Technologie NoFrost Dual vás zbaví nutnosti zdlouhavého odmrazování – chladný vzduch proudí rovnoměrně, snižuje vlhkost a brání tvorbě ledu na stěnách i potravinách. Díky technologii CoolSense se chladnička přizpůsobí vašim návykům – rozpozná, jak často otevíráte dvířka, a automaticky upravuje teplotu tak, aby potraviny zůstaly čerstvé co nejdéle a spotřeba energie byla co nejnižší. Funkce CoolConvert přináší praktickou flexibilitu, kdykoli potřebujete více prostoru pro nápoje nebo občerstvení – jedním dotykem proměníte mrazák na chladničku nebo velkou nulovou zónu. Invertorový kompresor zajišťuje tichý chod, stabilní teplotu a nižší spotřebu energie – ideální pro moderní, úspornou domácnost. Díky systému Multi AirFlow proudí chladný vzduch rovnoměrně po celém prostoru, takže vaše potraviny jsou správně uchované bez ohledu na to, kam je uložíte. Objemná zásuvka VitaBox vytváří ideální podmínky pro dlouhodobé uchování čerstvého ovoce a zeleniny – plného chuti i vitamínů. Chladnička se snadno přizpůsobí vaší kuchyni – dvířka umožňují změnu směru otevírání a výškově nastavitelné skleněné police jsou dostatečně odolné i pro velké hrnce a těžší potraviny. Extra tichý provoz je velkou výhodou – chladnička je ideální i do kuchyně propojené s obývacím pokojem nebo jídelnou. Její chod je téměř neslyšitelný, takže vás nebude rušit ani v noci.",
