      "description": "MORA VDIMS 78H C PureMatt s matným sklem nové generace spojuje moderní vzhled s praktičností a vysokou odolností. Matný povrch odráží až o 80 % méně světla než běžné lesklé sklo, čímž omezuje nepříjemné odlesky a dodává varné desce jemný, prémiový vzhled. Otisky prstů jsou navíc méně viditelné, takže si deska déle zachová čistý a upravený vzhled. Matný povrch je také až 5× odolnější proti poškrábání, a zůstává tak krásný i při každodenním používání. Praktické broušené hrany umožňují snadnou montáž i do roviny s pracovní deskou, díky čemuž varná deska elegantně zapadne do každé kuchyně. Nabízí 4 indukční varné zóny a funkci SuperBoost, která krátkodobě zvýší výkon a výrazně zkrátí čas potřebný k ohřevu. Funkce ConnectZone jediným dotykem propojí dvě levé varné zóny do jedné velké. Vznikne tak prostorná varná plocha ideální pro velké pánve a hrnce, nebo ji můžete využít pro současné vaření ve dvou či třech menších nádobách najednou. O přesné načasování se postará Timer a kuchyňská minutka TimeMinutes, zatímco funkce Pause umožní vaření kdykoli na chvíli přerušit a následně pokračovat s původním nastavením. Samozřejmostí je také dětská pojistka, která zabraňuje nechtěnému zapnutí varné desky a zvyšuje bezpečnost při používání v domácnosti.",
