      "description": "Černá volně stojící mikrovlnná trouba MORA MT 423 B s objemem 23 litrů nabízí dostatek prostoru i pro větší talíře a rodinné porce. Spolehlivě zvládne rychlé vaření, ohřívání i rozmrazování – ideální pomocník pro každodenní kuchařské výzvy. Díky pěti úrovním výkonu si snadno přizpůsobíte intenzitu ohřevu podle typu jídla. Jednoduché mechanické ovládání umožňuje nastavit čas až na 60 minut a zaručuje, že příprava pokrmů bude vždy pohodlná a bez starostí. Účinný program rozmrazování zajistí rovnoměrné rozmrazení potravin bez uvařených okrajů či zmrzlého středu. Mikrovlnný ohřev pracuje rychle a efektivně, aby bylo vaše jídlo teplé, chutné a připravené během několika minut. Díky praktickým přednastaveným programům si snadno poradí i s oblíbenými jídly, jako je popcorn, pizza nebo těstoviny – stačí zvolit typ pokrmu a hmotnost, o zbytek se postará sama. Nechybí ani automatické bezpečnostní vypnutí, které zastaví provoz při otevření dvířek. MORA MT 423 B je mikrovlnná trouba, která spojuje jednoduchost, spolehlivost a elegantní design s chytrými funkcemi – ideální volba pro všechny, kteří očekávají od mikrovlnky víc než jen ohřev.",
